mapper.select:
select 
from project_measures pm
inner join snapshots analysis on analysis.uuid = pm.analysis_uuid
where
pm.component_uuid = #{query.componentUuid, jdbcType=VARCHAR}

  and analysis.created_at>=#{query.from, jdbcType=BIGINT}


  and analysis.created_at<#{query.to, jdbcType=BIGINT}

and pm.metric_uuid in #{metricUuid, jdbcType=VARCHAR}
and analysis.status=#{query.status, jdbcType=VARCHAR}

select p.uuid as projectUuid, s.created_at as analysisDate, m.name as metricKey, pm.value as value, pm.text_value as textValue from snapshots s inner join project_branches pb on pb.uuid = s.root_component_uuid and pb.is_main = ${_true} inner join projects p on p.uuid = pb.project_uuid inner join project_measures pm on pm.analysis_uuid = s.uuid and pm.component_uuid = s.root_component_uuid inner join metrics m on m.uuid = pm.metric_uuid where p.organization_uuid = #{organizationUuid,jdbcType=VARCHAR} and p.qualifier = 'TRK' and s.status = 'P' and s.created_at >= #{fromDate,jdbcType=BIGINT} and s.created_at < #{toDate,jdbcType=BIGINT} and m.name in
#{metricKey,jdbcType=VARCHAR}
order by s.created_at
